<?php $money = static fn($value) => 'R$ ' . number_format((float) $value, 2, ',', '.'); $typeLabels = ['checking'=>'Conta corrente','savings'=>'Poupança','investment'=>'Investimento','cash'=>'Carteira / dinheiro','other'=>'Outros']; ?>
<section class="hero-row compact-hero"><div><span class="eyebrow">Onde está seu dinheiro?</span><h2 class="page-heading">Contas</h2><p class="page-subtitle">Acompanhe saldos e organize suas contas financeiras.</p></div><a class="button button-primary" href="/contas/nova"><span>+</span> Nova conta</a></section>
<section class="account-grid"><?php foreach ($accounts as $account): ?><article class="account-card <?= $account->status === 'inactive' ? 'is-inactive' : '' ?>"><div class="account-card-top"><span class="account-symbol">◒</span><span class="status-badge status-<?= $account->status ?>"><?= $account->status === 'active' ? 'Ativa' : 'Inativa' ?></span></div><h3><?= htmlspecialchars($account->name) ?></h3><p><?= htmlspecialchars($account->bank_name ?: ($typeLabels[$account->account_type] ?? 'Conta')) ?></p><strong><?= $money($account->current_balance) ?></strong><small><?= htmlspecialchars($typeLabels[$account->account_type] ?? 'Conta') ?> · inicial <?= $money($account->initial_balance) ?></small><div class="card-actions"><a href="/contas/<?= (int) $account->id ?>/editar">Editar</a><form method="post" action="/contas/<?= (int) $account->id ?>/toggle"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><button type="submit"><?= $account->status === 'active' ? 'Desativar' : 'Ativar' ?></button></form><form method="post" action="/contas/<?= (int) $account->id ?>/excluir" data-confirm="Remover esta conta?"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'] ?? '') ?>"><button type="submit" class="danger-text">Excluir</button></form></div></article><?php endforeach; ?><?php if (!$accounts): ?><div class="empty-state full-span"><span class="empty-icon">◒</span><h3>Adicione sua primeira conta</h3><p>Cadastre uma conta corrente, poupança, carteira ou investimento para começar.</p><a class="button button-primary" href="/contas/nova">Cadastrar conta</a></div><?php endif; ?></section>
